(function () {
  var h = hdrs || {};
  var distId = String(h['x-param-distribution_id'] || '');
  if (distId === '') {
    // x-url on a tenant gateway is /<gateway-id>/<mapping path>, so the route
    // param is the second-to-last segment of /d/<id>/bind. Measured: the
    // deployed cerberus sends NO x-param-* headers at all, so this fallback is
    // not a fallback -- it is the only route, and counting from the front gets
    // the gateway id.
    var u = String(h['x-url'] || '').split('/');
    distId = u.length >= 2 ? u[u.length - 2] : '';
  }
  var p = trg || {};
  var quoteId = String(p.quote_id == null ? '' : p.quote_id);
  if (!/^[A-Za-z0-9_-]{1,128}$/.test(quoteId)) quoteId = '';
  var problems = [];
  if (distId === '') problems.push('no distribution id on the request path');
  if (quoteId === '') problems.push('missing or malformed quote_id');
  return {
    ok: problems.length === 0,
    problems: problems,
    distribution_id: distId,
    quote_id: quoteId,
    inception_date: String(p.inception_date || ''),
    policyholder_name: String(p.policyholder_name || ''),
    broker_email: String(p.broker_email || ''),
    broker_filter: JSON.stringify([{ field: 'distribution_id', keyword: distId }]),
    decision_filter: JSON.stringify([{ field: 'quote_id', keyword: quoteId }])
  };
})();

(function () {
  if (!ing.ok) return { action: 'refuse', accepted: false, reason: ing.problems.join('; '), quote_id: ing.quote_id, decision_id: '' };

  var acct = String((accounts && accounts[ing.distribution_id]) || '');
  if (acct === '') return { action: 'refuse', accepted: false, reason: 'distribution ' + ing.distribution_id + ' has no account registered', quote_id: ing.quote_id, decision_id: '' };

  var brows = (brk && brk.results) ? brk.results : [];
  var bseen = {}, buniq = [];
  for (var i = 0; i < brows.length; i++) { var b = brows[i] || {}; if (!b.id || bseen[b.id]) continue; bseen[b.id] = true; buniq.push(b); }
  if (buniq.length === 0) return { action: 'refuse', accepted: false, reason: 'no distribution registered as ' + ing.distribution_id, quote_id: ing.quote_id, decision_id: '' };
  var bd = buniq[0].data || {};
  if (String(bd.broker_status) !== 'active') return { action: 'refuse', accepted: false, reason: 'distribution ' + ing.distribution_id + ' is ' + String(bd.broker_status), quote_id: ing.quote_id, decision_id: '' };

  var drows = (decs && decs.results) ? decs.results : [];
  var dseen = {}, best = null, bound = null, foreign = 0;
  for (var j = 0; j < drows.length; j++) {
    var r = drows[j] || {};
    if (!r.id || dseen[r.id]) continue;
    dseen[r.id] = true;
    var d = r.data || {};
    if (String(d.distributor_account_id || '') !== acct) { foreign++; continue; }
    if (String(d.outcome) === 'BOUND' || String(d.policy_number || '') !== '') {
      if (bound === null || Number(d.decision_seq || 0) > Number((bound.data && bound.data.decision_seq) || 0)) bound = r;
    }
    if (String(d.outcome) === 'ACCEPT') {
      if (best === null || Number(d.decision_seq || 0) > Number((best.data && best.data.decision_seq) || 0)) best = r;
    }
  }

  // Idempotency on quote_id: a duplicate bind returns the first outcome, never
  // a second policy. quote-bind's own CHECK_EXISTING_POLICY is the second line
  // of defence, not the first -- by the time it runs a counter may already have
  // been touched.
  if (bound !== null) {
    return { action: 'already_bound', accepted: true, reason: 'this quote is already bound', quote_id: ing.quote_id,
             decision_id: bound.id, policy_number: String((bound.data && bound.data.policy_number) || '') };
  }
  if (best === null) {
    return { action: 'refuse', accepted: false,
             reason: foreign > 0
               ? 'no ACCEPT decision for this quote belongs to ' + ing.distribution_id + ' (' + foreign + ' decision(s) belong to another distributor)'
               : 'no ACCEPT decision for this quote',
             quote_id: ing.quote_id, decision_id: '' };
  }
  var bdata = best.data || {};
  return { action: 'bind', accepted: true, reason: '', quote_id: ing.quote_id, decision_id: best.id,
           broker_id: String(bd.broker_id || ''),
           policyholder_name: ing.policyholder_name || String(bdata.policyholder_name || ''),
           broker_email: ing.broker_email || String(bd.primary_contact_email || ''),
           inception_date: ing.inception_date };
})();

(function () {
  var rows = (q && q.results) ? q.results : [];
  var seen = {}, bound = null, newest = null;
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i] || {};
    if (!r.id || seen[r.id]) continue;
    seen[r.id] = true;
    var seq = Number((r.data && r.data.decision_seq) || 0);
    if (newest === null || seq > Number((newest.data && newest.data.decision_seq) || 0)) newest = r;
    if (String(r.data && r.data.outcome) === 'BOUND' || String((r.data && r.data.policy_number) || '') !== '') {
      if (bound === null || seq > Number((bound.data && bound.data.decision_seq) || 0)) bound = r;
    }
  }
  return {
    decision_id: bound ? bound.id : '',
    found: bound !== null,
    reason: bound !== null ? '' : 'the BOUND decision is not visible in the index yet; the bind itself succeeded'
  };
})();
